{"version":3,"file":"instructor-main.jsdbx","sources":["../../src/client/services/InstructorService.js","../../src/client/components/instructor/CourseCreationForm.jsx","../../src/client/components/instructor/CourseManagement.jsx","../../src/client/components/instructor/LessonManagement.jsx","../../src/client/components/instructor/AssessmentCreation.jsx","../../src/client/components/instructor/InstructorApp.css","../../src/client/instructor-main.jsx","../../src/client/components/instructor/InstructorApp.jsx"],"sourcesContent":["export class InstructorService {
  constructor() {
    this.scopePrefix = 'x_1879300_learning';
  }

  // Generic API call helper with comprehensive error handling
  async apiCall(endpoint, options = {}) {
    try {
      const response = await fetch(endpoint, {
        ...options,
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
          'X-UserToken': window.g_ck,
          ...options.headers
        }
      });

      let responseData;
      try {
        responseData = await response.json();
      } catch (parseError) {
        console.error('JSON parse error:', parseError);
        throw new Error('Invalid response format from server');
      }

      if (!response.ok) {
        const errorMessage = responseData?.error?.message || 
          responseData?.message || 
          `HTTP ${response.status}: ${response.statusText}`;
        throw new Error(errorMessage);
      }

      return responseData;
    } catch (error) {
      console.error('API call failed:', error);
      throw error;
    }
  }

  // Get current logged in user
  async getCurrentUser() {
    const response = await this.apiCall('/api/now/table/sys_user?sysparm_query=user_name=javascript:gs.getUserName()&sysparm_display_value=all');
    return response.result?.[0] || null;
  }

  // Course management
  async createCourse(courseData) {
    const response = await this.apiCall(`/api/now/table/${this.scopePrefix}_courses`, {
      method: 'POST',
      body: JSON.stringify(courseData)
    });
    return response.result;
  }

  async getCourses() {
    const response = await this.apiCall(`/api/now/table/${this.scopePrefix}_courses?sysparm_display_value=all&sysparm_order=sys_created_on`);
    return response.result || [];
  }

  async getCoursesByInstructor(instructorSysId) {
    const encodedQuery = `instructor=${instructorSysId}`;
    const response = await this.apiCall(`/api/now/table/${this.scopePrefix}_courses?sysparm_query=${encodedQuery}&sysparm_display_value=all&sysparm_order=sys_created_on`);
    return response.result || [];
  }

  async updateCourse(courseSysId, courseData) {
    const response = await this.apiCall(`/api/now/table/${this.scopePrefix}_courses/${courseSysId}`, {
      method: 'PATCH',
      body: JSON.stringify(courseData)
    });
    return response.result;
  }

  // Lesson management
  async createLesson(lessonData) {
    const response = await this.apiCall(`/api/now/table/${this.scopePrefix}_lessons`, {
      method: 'POST',
      body: JSON.stringify(lessonData)
    });
    return response.result;
  }

  async getLessonsByCourse(courseSysId) {
    const encodedQuery = `course=${courseSysId}`;
    const response = await this.apiCall(`/api/now/table/${this.scopePrefix}_lessons?sysparm_query=${encodedQuery}&sysparm_display_value=all&sysparm_order=sequence`);
    return response.result || [];
  }

  async updateLesson(lessonSysId, lessonData) {
    const response = await this.apiCall(`/api/now/table/${this.scopePrefix}_lessons/${lessonSysId}`, {
      method: 'PATCH',
      body: JSON.stringify(lessonData)
    });
    return response.result;
  }

  async deleteLesson(lessonSysId) {
    const response = await this.apiCall(`/api/now/table/${this.scopePrefix}_lessons/${lessonSysId}`, {
      method: 'DELETE'
    });
    return response.ok || true;
  }

  // Assessment management
  async createAssessment(assessmentData) {
    const response = await this.apiCall(`/api/now/table/${this.scopePrefix}_assessments`, {
      method: 'POST',
      body: JSON.stringify(assessmentData)
    });
    return response.result;
  }

  async getAssessmentsByCourse(courseSysId) {
    const encodedQuery = `course=${courseSysId}`;
    const response = await this.apiCall(`/api/now/table/${this.scopePrefix}_assessments?sysparm_query=${encodedQuery}&sysparm_display_value=all&sysparm_order=sys_created_on`);
    return response.result || [];
  }

  // Question management
  async createQuestion(questionData) {
    const response = await this.apiCall(`/api/now/table/${this.scopePrefix}_questions`, {
      method: 'POST',
      body: JSON.stringify(questionData)
    });
    return response.result;
  }

  async getQuestionsByAssessment(assessmentSysId) {
    const encodedQuery = `assessment=${assessmentSysId}`;
    const response = await this.apiCall(`/api/now/table/${this.scopePrefix}_questions?sysparm_query=${encodedQuery}&sysparm_display_value=all&sysparm_order=sequence`);
    return response.result || [];
  }

  // Question choices for multiple choice questions
  async createQuestionChoice(choiceData) {
    const response = await this.apiCall(`/api/now/table/${this.scopePrefix}_question_choices`, {
      method: 'POST',
      body: JSON.stringify(choiceData)
    });
    return response.result;
  }

  async getChoicesByQuestion(questionSysId) {
    const encodedQuery = `question=${questionSysId}`;
    const response = await this.apiCall(`/api/now/table/${this.scopePrefix}_question_choices?sysparm_query=${encodedQuery}&sysparm_display_value=all&sysparm_order=sequence`);
    return response.result || [];
  }

  // Supporting materials
  async createMaterial(materialData) {
    const response = await this.apiCall(`/api/now/table/${this.scopePrefix}_materials`, {
      method: 'POST',
      body: JSON.stringify(materialData)
    });
    return response.result;
  }

  async getMaterialsByLesson(lessonSysId) {
    const encodedQuery = `lesson=${lessonSysId}`;
    const response = await this.apiCall(`/api/now/table/${this.scopePrefix}_materials?sysparm_query=${encodedQuery}&sysparm_display_value=all&sysparm_order=sys_created_on`);
    return response.result || [];
  }

  // Student progress and enrollment tracking (for instructors to view)
  async getStudentEnrollments(courseSysId) {
    const encodedQuery = `course=${courseSysId}`;
    const response = await this.apiCall(`/api/now/table/${this.scopePrefix}_student_enrollments?sysparm_query=${encodedQuery}&sysparm_display_value=all&sysparm_order=sys_created_on`);
    return response.result || [];
  }

  async getAssessmentAttempts(courseSysId) {
    // Get attempts for assessments in this course
    const assessments = await this.getAssessmentsByCourse(courseSysId);
    if (!assessments.length) return [];

    const assessmentIds = assessments.map(a => 
      typeof a.sys_id === 'object' ? a.sys_id.value : a.sys_id
    ).join(',');

    const encodedQuery = `assessmentIN${assessmentIds}`;
    const response = await this.apiCall(`/api/now/table/${this.scopePrefix}_assessment_attempts?sysparm_query=${encodedQuery}&sysparm_display_value=all&sysparm_order=sys_created_on`);
    return response.result || [];
  }
}","import React, { useState, useEffect } from 'react';
import { InstructorService } from '../../services/InstructorService.js';

export default function CourseCreationForm({ onCourseCreated }) {
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    category: '',
    difficulty_level: '',
    estimated_duration: '',
    status: 'draft'
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(false);
  const [service] = useState(() => new InstructorService());

  const categories = [
    'Programming',
    'Web Development', 
    'Data Science',
    'DevOps',
    'Cybersecurity',
    'Cloud Computing',
    'Mobile Development',
    'Database',
    'AI/Machine Learning',
    'Other'
  ];

  const difficultyLevels = [
    { value: 'beginner', label: 'Beginner' },
    { value: 'intermediate', label: 'Intermediate' }, 
    { value: 'advanced', label: 'Advanced' }
  ];

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setSuccess(false);

    try {
      // Get current user info (instructor)
      const currentUser = await service.getCurrentUser();
      const instructorSysId = typeof currentUser.sys_id === 'object' 
        ? currentUser.sys_id.value 
        : currentUser.sys_id;

      const courseData = {
        ...formData,
        instructor: instructorSysId,
        created_by: instructorSysId,
        is_active: true,
        published: formData.status === 'published'
      };

      await service.createCourse(courseData);
      setSuccess(true);
      setFormData({
        title: '',
        description: '',
        category: '',
        difficulty_level: '',
        estimated_duration: '',
        status: 'draft'
      });

      // Notify parent component
      if (onCourseCreated) {
        setTimeout(() => onCourseCreated(), 1500);
      }

    } catch (err) {
      console.error('Error creating course:', err);
      setError('Failed to create course. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  if (success) {
    return (
      <div className="form-container">
        <div className="success">
          ✅ Course created successfully! Redirecting to course management...
        </div>
      </div>
    );
  }

  return (
    <div className="form-container">
      <h2>🆕 Create New Course</h2>
      <p>Fill out the form below to create a new technical course for your students.</p>

      {error && <div className="error">{error}</div>}

      <form onSubmit={handleSubmit}>
        <div className="form-group">
          <label htmlFor="title">Course Title *</label>
          <input
            type="text"
            id="title"
            name="title"
            value={formData.title}
            onChange={handleChange}
            required
            placeholder="e.g., Advanced React Development"
          />
        </div>

        <div className="form-group">
          <label htmlFor="description">Course Description</label>
          <textarea
            id="description"
            name="description"
            value={formData.description}
            onChange={handleChange}
            placeholder="Describe what students will learn in this course..."
          />
        </div>

        <div className="form-row">
          <div className="form-group">
            <label htmlFor="category">Category *</label>
            <select
              id="category"
              name="category"
              value={formData.category}
              onChange={handleChange}
              required
            >
              <option value="">Select Category</option>
              {categories.map(cat => (
                <option key={cat} value={cat}>{cat}</option>
              ))}
            </select>
          </div>

          <div className="form-group">
            <label htmlFor="difficulty_level">Difficulty Level *</label>
            <select
              id="difficulty_level"
              name="difficulty_level"
              value={formData.difficulty_level}
              onChange={handleChange}
              required
            >
              <option value="">Select Difficulty</option>
              {difficultyLevels.map(level => (
                <option key={level.value} value={level.value}>
                  {level.label}
                </option>
              ))}
            </select>
          </div>
        </div>

        <div className="form-row">
          <div className="form-group">
            <label htmlFor="estimated_duration">Estimated Duration (hours)</label>
            <input
              type="number"
              id="estimated_duration"
              name="estimated_duration"
              value={formData.estimated_duration}
              onChange={handleChange}
              min="1"
              max="200"
              placeholder="e.g., 12"
            />
          </div>

          <div className="form-group">
            <label htmlFor="status">Initial Status</label>
            <select
              id="status"
              name="status"
              value={formData.status}
              onChange={handleChange}
            >
              <option value="draft">Draft (not visible to students)</option>
              <option value="published">Published (visible to students)</option>
            </select>
          </div>
        </div>

        <div className="form-actions">
          <button
            type="button"
            className="btn btn-secondary"
            onClick={() => setFormData({
              title: '',
              description: '',
              category: '',
              difficulty_level: '',
              estimated_duration: '',
              status: 'draft'
            })}
          >
            Reset Form
          </button>
          <button
            type="submit"
            className="btn btn-primary"
            disabled={loading}
          >
            {loading ? '⏳ Creating...' : '✨ Create Course'}
          </button>
        </div>
      </form>
    </div>
  );
}","import React, { useState, useEffect } from 'react';
import { InstructorService } from '../../services/InstructorService.js';

export default function CourseManagement({ onCourseSelect, selectedCourse }) {
  const [courses, setCourses] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [service] = useState(() => new InstructorService());

  useEffect(() => {
    loadCourses();
  }, []);

  const loadCourses = async () => {
    try {
      setLoading(true);
      const currentUser = await service.getCurrentUser();
      const instructorSysId = typeof currentUser.sys_id === 'object' 
        ? currentUser.sys_id.value 
        : currentUser.sys_id;

      const coursesData = await service.getCoursesByInstructor(instructorSysId);
      setCourses(coursesData);
    } catch (err) {
      console.error('Error loading courses:', err);
      setError('Failed to load courses');
    } finally {
      setLoading(false);
    }
  };

  const toggleCourseStatus = async (course) => {
    try {
      const courseSysId = typeof course.sys_id === 'object' ? course.sys_id.value : course.sys_id;
      const currentStatus = course.published === 'true' || course.published === true;

      await service.updateCourse(courseSysId, {
        published: !currentStatus
      });

      await loadCourses(); // Refresh the list
    } catch (err) {
      console.error('Error updating course status:', err);
      setError('Failed to update course status');
    }
  };

  if (loading) {
    return (
      <div className="form-container">
        <div className="loading">📚 Loading your courses...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="form-container">
        <div className="error">{error}</div>
        <button onClick={loadCourses} className="btn btn-primary">Try Again</button>
      </div>
    );
  }

  return (
    <div className="form-container">
      <h2>📚 My Courses</h2>
      <p>Manage your existing courses and view student engagement.</p>

      {courses.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '3rem', color: '#7f8c8d' }}>
          <p>📋 No courses created yet.</p>
          <p>Use the "Create Course" tab to add your first course!</p>
        </div>
      ) : (
        <div style={{ display: 'grid', gap: '1rem' }}>
          {courses.map(course => {
            const title = typeof course.title === 'object' ? course.title.display_value : course.title;
            const category = typeof course.category === 'object' ? course.category.display_value : course.category;
            const difficulty = typeof course.difficulty_level === 'object' ? course.difficulty_level.display_value : course.difficulty_level;
            const isPublished = course.published === 'true' || course.published === true;
            const courseSysId = typeof course.sys_id === 'object' ? course.sys_id.value : course.sys_id;

            return (
              <div 
                key={courseSysId}
                style={{
                  background: 'white',
                  padding: '1.5rem',
                  borderRadius: '12px',
                  border: selectedCourse?.sys_id === courseSysId ? '2px solid #3498db' : '1px solid #ecf0f1',
                  boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
                  cursor: 'pointer',
                  transition: 'all 0.3s ease'
                }}
                onClick={() => onCourseSelect(course)}
              >
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                  <div style={{ flex: 1 }}>
                    <h3 style={{ margin: '0 0 0.5rem 0', color: '#2c3e50' }}>
                      {title}
                      {selectedCourse?.sys_id === courseSysId && <span style={{ marginLeft: '0.5rem', color: '#3498db' }}>👈 Selected</span>}
                    </h3>
                    <div style={{ display: 'flex', gap: '1rem', marginBottom: '1rem' }}>
                      <span style={{ 
                        background: '#ecf0f1', 
                        padding: '0.25rem 0.5rem', 
                        borderRadius: '4px', 
                        fontSize: '0.875rem',
                        color: '#2c3e50'
                      }}>
                        📂 {category}
                      </span>
                      <span style={{ 
                        background: difficulty === 'beginner' ? '#e8f5e8' : difficulty === 'intermediate' ? '#fff3cd' : '#f8d7da',
                        color: difficulty === 'beginner' ? '#155724' : difficulty === 'intermediate' ? '#856404' : '#721c24',
                        padding: '0.25rem 0.5rem', 
                        borderRadius: '4px', 
                        fontSize: '0.875rem'
                      }}>
                        🎯 {difficulty}
                      </span>
                      <span style={{ 
                        background: isPublished ? '#d4edda' : '#f8d7da',
                        color: isPublished ? '#155724' : '#721c24',
                        padding: '0.25rem 0.5rem', 
                        borderRadius: '4px', 
                        fontSize: '0.875rem'
                      }}>
                        {isPublished ? '🟢 Published' : '🔴 Draft'}
                      </span>
                    </div>
                  </div>
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      toggleCourseStatus(course);
                    }}
                    style={{
                      background: isPublished ? '#e74c3c' : '#27ae60',
                      color: 'white',
                      border: 'none',
                      padding: '0.5rem 1rem',
                      borderRadius: '6px',
                      cursor: 'pointer',
                      fontSize: '0.875rem'
                    }}
                  >
                    {isPublished ? 'Unpublish' : 'Publish'}
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}","import React, { useState } from 'react';

export default function LessonManagement({ selectedCourse, onCourseChange }) {
